preConditionHook:
// Lowest(low[1], rangeLookback) / Highest(high[1], rangeLookback): the window
// ENDS ONE BAR BACK, bars 1..rangeLookback, so the current bar cannot define
// the level it is being tested against.
// Mirrors EasyLanguage's Extremes(): seeded on the first bar of the window,
// scanning the rest, strict comparison so a tie keeps the earliest bar.
// Extremes is EL SOURCE, so its comparisons carry the relational tolerance and
// these use el_lt/el_gt rather than < and >.
lowestLow = low[1];
highestHigh = high[1];
for (int i = 2; i <= (int)rangeLookback; ++i) {
    if (el_lt(low[i], lowestLow)) lowestLow = low[i];
    if (el_gt(high[i], highestHigh)) highestHigh = high[i];
}
